={{ (() => {
  const escapar = (v) => "'" + String(v).replace(/\\/g, '\\\\').replace(/'/g, "\\'") + "'";
  const numero = (v) => (v === null || v === undefined) ? 'NULL' : Number(v);
  const idObra = numero($json.id_obra);
  return "INSERT INTO rest_restricoes (id_obra, total, restricoes) " +
    "SELECT " + idObra + ", " + numero($json.total) + ", CAST(" + escapar(JSON.stringify($json.restricoes || [])) + " AS JSON) " +
    "FROM DUAL WHERE EXISTS (SELECT 1 FROM obras WHERE id = " + idObra + ") " +
    "ON DUPLICATE KEY UPDATE total = VALUES(total), restricoes = VALUES(restricoes)";
})() }}
